HAL_PWR_EnableWakeUpPin.exampleCode:
/* 用 WKUP 引脚（PA0）唤醒待机模式 */
HAL_PWR_EnableWakeUpPin(PWR_WAKEUP_PIN1);
HAL_PWR_EnterSTANDBYMode();

HAL_PWR_EnterSTANDBYMode.exampleCode:
/* 待机：功耗最低，SRAM 丢失，唤醒等同复位 */
HAL_PWR_EnterSTANDBYMode();
/* 这行永远不会执行到（除非被复位唤醒后重新跑 main） */

HAL_PWR_EnterSTOPMode.exampleCode:
/* 进入 STOP 模式，等中断唤醒 */
HAL_PWR_EnterSTOPMode(PWR_LOWPOWERREGULATOR_ON, PWR_STOPENTRY_WFI);

/* 唤醒后时钟退回 HSI，必须重配时钟树！ */
SystemClock_Config();
